"use client";

import { useEffect, useMemo, useState, type KeyboardEvent } from "react";
import { buildClosureEpisodes, groupInspectionRows, matchCohort, recurrenceAnalysis, timelineAnalysis, type ClosureEpisode, type CohortFilters, type InspectionEvent, type RawInspectionRow } from "../lib/closure-analysis";
import type { BoroughMapPath } from "../lib/inspections";
import { BookChapters } from "./BookChapters";
import { SampleLauncher } from "./SampleLauncher";

const fmt=new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric",year:"numeric"});
type FetchState="idle"|"loading"|"success"|"empty"|"error";
type DirectoryState="idle"|"loading"|"success"|"error";
type MatchTier="exact"|"strong"|"broad";
function buildComparison(selected:ClosureEpisode,episodes:ClosureEpisode[],filters:CohortFilters,tier:MatchTier,codes=selected.closure.codes.map(c=>c.code)){const selectedCodes=new Set(codes);const criticalCodes=selected.closure.codes.filter(c=>c.critical&&selectedCodes.has(c.code)).map(c=>c.code);const strongMinimum=Math.max(1,Math.ceil(selectedCodes.size*2/3));const broadMinimum=Math.max(1,Math.ceil(selectedCodes.size/2));return matchCohort(selected,episodes,{...filters,minSharedCodes:0}).filter(e=>{const episodeCodes=new Set(e.closure.codes.map(c=>c.code));const overlap=[...selectedCodes].filter(code=>episodeCodes.has(code)).length;if(tier==="exact")return overlap===selectedCodes.size&&episodeCodes.size===selectedCodes.size;if(tier==="strong")return overlap>=strongMinimum&&criticalCodes.every(code=>episodeCodes.has(code));return overlap>=broadMinimum})}
function recommendedTier(selected:ClosureEpisode,episodes:ClosureEpisode[],filters:CohortFilters):MatchTier{if(buildComparison(selected,episodes,filters,"exact").length)return"exact";if(buildComparison(selected,episodes,filters,"strong").length)return"strong";return"broad"}

export function ConnectedJourney({episodes,events,boroughMap,fetchedAt,dateRange}:{episodes:ClosureEpisode[];events:InspectionEvent[];boroughMap:BoroughMapPath[];fetchedAt:string;dateRange:string}){
  const sample=useMemo(()=>episodes.find(e=>e.closure.codes.length>=2&&buildComparison(e,episodes,{scope:"city",burdenTolerance:99,periodYears:2,inspectionType:true,minSharedCodes:0},"exact").length>=2)??episodes.find(e=>e.reopening&&e.closure.codes.length>=3)??episodes[0],[episodes]);
  const [selected,setSelected]=useState<ClosureEpisode|null>(null);
  const [selectedNeverClosed,setSelectedNeverClosed]=useState(false);
  const [query,setQuery]=useState("");
  const [directoryMatches,setDirectoryMatches]=useState<InspectionEvent[]>([]);
  const [directoryState,setDirectoryState]=useState<DirectoryState>("idle");
  const [searchFocused,setSearchFocused]=useState(false);
  const [filters,setFilters]=useState<CohortFilters>({scope:"borough",burdenTolerance:2,periodYears:2,inspectionType:true,minSharedCodes:1});
  const [selectedCodes,setSelectedCodes]=useState<string[]>([]);
  const [matchTier,setMatchTier]=useState<MatchTier|null>(null);
  const [comparisonMode,setComparisonMode]=useState<"exact"|"custom"|null>(null);
  const [lockedIds,setLockedIds]=useState<string[]>([]);
  const [latest,setLatest]=useState<InspectionEvent[]>([]);
  const [fetchState,setFetchState]=useState<FetchState>("idle");
  const [refreshKey,setRefreshKey]=useState(0);
  const [verifiedAt,setVerifiedAt]=useState("");
  const [activeResult,setActiveResult]=useState(-1);
  const [searchRefreshKey,setSearchRefreshKey]=useState(0);
  const [peerSaved,setPeerSaved]=useState(false);
  const [patternTab,setPatternTab]=useState<"absent"|"remained"|"appeared">("remained");
  const matches=useMemo(()=>{const q=query.trim().toLowerCase();return q.length<2?[]:episodes.filter(e=>`${e.name} ${e.camis} ${e.borough} ${e.zipcode}`.toLowerCase().includes(q)).slice(0,7)},[episodes,query]);
  const noMatches=query.trim().length>=2&&directoryState==="success"&&matches.length===0&&directoryMatches.length===0;
  const activeCodes=comparisonMode==="custom"?selectedCodes:selected?.closure.codes.map(c=>c.code)??[];
  const draftCohort=useMemo(()=>selected&&comparisonMode&&(comparisonMode==="exact"||matchTier)&&activeCodes.length?buildComparison(selected,episodes,filters,comparisonMode==="exact"?"exact":matchTier!,activeCodes):[],[selected,episodes,filters,comparisonMode,matchTier,activeCodes]);
  const cohort=useMemo(()=>{const ids=new Set(lockedIds);return episodes.filter(e=>ids.has(e.id))},[episodes,lockedIds]);
  const cohortDirty=useMemo(()=>draftCohort.map(e=>e.id).sort().join("|")!==[...lockedIds].sort().join("|"),[draftCohort,lockedIds]);
  const transitions=useMemo(()=>transitionRows(cohort),[cohort]);
  const recurrence=useMemo(()=>recurrenceAnalysis(cohort,fetchedAt.slice(0,10)),[cohort,fetchedAt]);
  const timeline=useMemo(()=>timelineAnalysis(cohort,fetchedAt.slice(0,10)),[cohort,fetchedAt]);
  const timingBuckets=useMemo(()=>[["0–3 days",0,3],["4–7 days",4,7],["8–14 days",8,14],["15–30 days",15,30],["31+ days",31,Infinity]] as const,[]);
  const commonTimingRange=useMemo(()=>timeline.values.length?[...timingBuckets].map(([label,min,max])=>({label,count:timeline.values.filter(value=>value>=min&&value<=max).length})).sort((a,b)=>b.count-a.count)[0]:null,[timeline.values,timingBuckets]);
  const latestRecords=useMemo(()=>{const source=fetchState==="success"?latest:events;if(!selected)return[];const records=source.filter(e=>e.camis===selected.camis).sort((a,b)=>b.date.localeCompare(a.date)||a.action.localeCompare(b.action)||a.id.localeCompare(b.id));const newestDate=records[0]?.date;return records.filter(e=>e.date===newestDate)},[events,fetchState,latest,selected]);
  const comparisonReady=fetchState==="success"&&(selectedNeverClosed||Boolean(comparisonMode&&(comparisonMode==="exact"||(selectedCodes.length&&matchTier&&filters.boroughOverride))));
  const searchResults=useMemo(()=>{const seen=new Set<string>();const closure=matches.map(episode=>({key:episode.id,event:episode.closure}));const directory=directoryMatches.map(event=>({key:`directory|${event.camis}`,event}));return [...closure,...directory].filter(item=>seen.has(item.event.camis)?false:(seen.add(item.event.camis),true)).slice(0,10)},[matches,directoryMatches]);

  useEffect(()=>{const q=query.trim();if(q.length<2){setDirectoryMatches([]);setDirectoryState("idle");setActiveResult(-1);return}const controller=new AbortController();const timer=window.setTimeout(()=>{setDirectoryState("loading");const safe=q.toUpperCase().replaceAll("'","''");const where=/^\d+$/.test(q)?`camis='${safe}'`:`dba like '${safe}%'`;const params=new URLSearchParams({"$select":"camis,dba,boro,building,street,zipcode,inspection_date,inspection_type,action,violation_code,violation_description,critical_flag,score,grade,grade_date,record_date,latitude,longitude","$where":where,"$order":"inspection_date DESC","$limit":"200"});fetch(`https://data.cityofnewyork.us/resource/43nn-pn8j.json?${params}`,{signal:controller.signal}).then(response=>response.ok?response.json():Promise.reject(new Error("search failed"))).then((rows:RawInspectionRow[])=>{const found=groupInspectionRows(rows).sort((a,b)=>b.date.localeCompare(a.date));const latestByCamis=new Map<string,InspectionEvent>();found.forEach(event=>{if(!latestByCamis.has(event.camis))latestByCamis.set(event.camis,event)});const localCamis=new Set(matches.map(item=>item.camis));setDirectoryMatches([...latestByCamis.values()].filter(event=>!localCamis.has(event.camis)).slice(0,10));setDirectoryState("success")}).catch(error=>{if(error instanceof DOMException&&error.name==="AbortError")return;setDirectoryMatches([]);setDirectoryState("error")})},300);return()=>{controller.abort();window.clearTimeout(timer)}},[query,matches,searchRefreshKey]);

  useEffect(()=>{if(!selected)return;const controller=new AbortController();setFetchState("loading");setSelectedNeverClosed(false);const [start,end]=dateRange.split("–");const params=new URLSearchParams({"$select":"camis,dba,boro,building,street,zipcode,inspection_date,inspection_type,action,violation_code,violation_description,critical_flag,score,grade,grade_date,record_date,latitude,longitude","$where":`camis='${selected.camis}' AND inspection_date >= '${start}T00:00:00.000' AND inspection_date <= '${end}T23:59:59.999'`,"$order":"inspection_date DESC,action","$limit":"5000"});fetch(`https://data.cityofnewyork.us/resource/43nn-pn8j.json?${params}`,{signal:controller.signal}).then(r=>{if(!r.ok)throw new Error("request failed");return r.json()}).then((rows:RawInspectionRow[])=>{const verifiedEvents=groupInspectionRows(rows).sort((a,b)=>b.date.localeCompare(a.date)||a.action.localeCompare(b.action));if(!verifiedEvents.length){setLatest([]);setFetchState("empty");return}const verifiedEpisodes=buildClosureEpisodes(verifiedEvents).filter(item=>item.camis===selected.camis);const authoritative=verifiedEpisodes[0];setLatest(verifiedEvents);setVerifiedAt(new Date().toISOString());if(authoritative){setSelected(authoritative);setSelectedNeverClosed(false);setSelectedCodes(authoritative.closure.codes.map(code=>code.code))}else{const newest=verifiedEvents[0];setSelected({id:`verified-no-closure|${newest.camis}`,camis:newest.camis,name:newest.name,borough:newest.borough,address:newest.address,zipcode:newest.zipcode,latitude:newest.latitude,longitude:newest.longitude,closure:newest,reopening:null,laterClosure:null,reopeningDays:null,laterClosureDays:null});setSelectedNeverClosed(true);setSelectedCodes([])}setComparisonMode(null);setLockedIds([]);setFetchState("success")}).catch(error=>{if(error instanceof DOMException&&error.name==="AbortError")return;setFetchState("error")});return()=>controller.abort()},[selected?.camis,refreshKey,dateRange]);
  useEffect(()=>{const reset=()=>{setSelected(null);setSelectedNeverClosed(false);setQuery("");setDirectoryMatches([]);setDirectoryState("idle");setSearchFocused(false);setSelectedCodes([]);setFilters({scope:"borough",burdenTolerance:2,periodYears:2,inspectionType:true,minSharedCodes:1});setMatchTier(null);setComparisonMode(null);setLockedIds([]);setLatest([]);setFetchState("idle");setVerifiedAt("");setPeerSaved(false);setPatternTab("remained")};window.addEventListener("six-days-reset",reset);return()=>window.removeEventListener("six-days-reset",reset)},[]);
  useEffect(()=>{if(!sample)return;const load=()=>choose(sample);window.addEventListener("six-days-load-sample",load);return()=>window.removeEventListener("six-days-load-sample",load)},[sample]);
  const chooseCandidate=(event:InspectionEvent)=>{const provisional:ClosureEpisode={id:`checking|${event.camis}`,camis:event.camis,name:event.name,borough:event.borough,address:event.address,zipcode:event.zipcode,latitude:event.latitude,longitude:event.longitude,closure:event,reopening:null,laterClosure:null,reopeningDays:null,laterClosureDays:null};setSelected(provisional);setSelectedNeverClosed(false);setQuery("");setDirectoryMatches([]);setDirectoryState("idle");setComparisonMode(null);setLockedIds([]);setLatest([]);setFetchState("loading");window.setTimeout(()=>window.dispatchEvent(new CustomEvent("six-days-go-step",{detail:"find"})),0)};
  const choose=(episode:ClosureEpisode)=>chooseCandidate(episode.closure);

  const unlockedThrough = !selected||fetchState!=="success" ? 1 : selectedNeverClosed ? 3 : cohort.length ? 4 : comparisonMode ? 3 : 2;
  const timingPage=<section className="book-chapter owner-step timeline-step" id="timeline"><Step n="03" title="Review matching records" question="Which closure records match the comparison I created?" impact="Review the records produced by your comparison"/><p className="step-intro">Step 4 applies the method selected in Step 3, shows the matching closure records, and then summarizes their recorded reopening timing.</p>{selected&&comparisonMode&&<><ExactBenchmark selected={selected} matches={cohort} mode={comparisonMode} codes={activeCodes} tier={comparisonMode==="exact"?"exact":matchTier}/>{cohort.length>0&&<PeerSetMap paths={boroughMap} episodes={cohort}/>}</>}{selected&&cohort.length?<><section className="timeline-answer" aria-label="Primary reopening-time result"><span>TYPICAL RECORDED REOPENING TIME</span><div><strong>{timeline.median??"—"}</strong><b>days</b></div><p>Based on {timeline.matched} of {timeline.total} matching closure records with a later reopening recorded.</p></section><div className="timeline-summary"><article><span>FAST CASES</span><strong>{timeline.values.filter(value=>value<=3).length} of {timeline.matched}</strong><p>received a reopening record within 3 days</p></article><article><span>MOST COMMON RANGE</span><strong>{commonTimingRange?.label??"Not available"}</strong><p>{commonTimingRange?`${commonTimingRange.count} of ${timeline.matched} recorded reopenings fell here`:"No reopening intervals were available"}</p></article><article><span>LONGER CASES</span><strong>{timeline.thresholds.find(item=>item.days===14)?.without??0}</strong><p>eligible cases had no reopening recorded by day 14</p></article></div><div className="timeline-evidence"><h3>Where the recorded reopenings occurred</h3><p>Each bar shows the share of matching cases with a later reopening record.</p><TimelineBars values={timeline.values}/></div><section className="delay-checkpoints"><div><span>PLANNING CHECKPOINTS</span><h3>Some cases remained unresolved longer</h3><p>These percentages include every matching closure old enough to measure at each checkpoint.</p></div><div className="delay-grid">{timeline.thresholds.map(item=><article key={item.days}>{item.eligible?<><span>NO REOPENING BY DAY {item.days}</span><strong>{item.rate.toFixed(1)}%</strong><p>{item.without} of {item.eligible} eligible cases</p></>:<><span>DAY {item.days}</span><strong>—</strong><p>Not enough cases old enough to measure</p></>}</article>)}</div></section><p className="plain-note"><strong>What this means:</strong> plan for more than one timing scenario. These are historical public-record intervals, not a prediction for {selected.name}.</p></>:selected&&comparisonMode?<p className="journey-empty">No closure records match the selected comparison. Return to Step 3 and adjust the method or parameters.</p>:<EmptyState/>}</section>;
  const selectedCodeSet=new Set(activeCodes);
  const ownTransitionRows=transitions.rows.filter(row=>selectedCodeSet.has(row.code));
  const ownRecurrence={...recurrence,codes:recurrence.codes.filter(row=>selectedCodeSet.has(row.code))};
  const patternPage=<section className="book-chapter owner-step" id="change"><Step n="04" title="Prioritize the recorded patterns" question="What happened to my violations in later public records?" impact="Shows which codes were absent or still recorded so the owner knows which documented areas merit closer discussion with DOHMH or a qualified adviser."/><p className="step-intro">Follow every violation from the exact-match benchmark into the restaurants’ next recorded reopening and, where observable, a later closure.</p>{selected&&cohort.length?<><div className="pattern-evidence-base"><article><span>EXACT-MATCH CLOSURES</span><strong>{cohort.length}</strong><p>saved from Step 2</p></article><i aria-hidden="true">→</i><article><span>REOPENING RECORDS</span><strong>{transitions.eligible}</strong><p>available for change analysis</p></article><i aria-hidden="true">→</i><article><span>LATER CLOSURES</span><strong>{recurrence.reclosed}</strong><p>available for recurrence analysis</p></article></div><ViolationOutcomeTable selected={selected} rows={ownTransitionRows} recurrence={ownRecurrence}/><details className="comparison-details secondary-patterns"><summary>See other codes first recorded at reopening <span>+</span></summary><div className="change-grid single"><TransitionList title="Other codes newly recorded" rows={transitions.rows.filter(row=>!selectedCodeSet.has(row.code)&&row.appeared>0).sort((a,b)=>b.appeared-a.appeared).slice(0,8)} value={row=>`${row.appeared} of ${transitions.eligible} · ${percent(row.appeared,transitions.eligible)}`}/></div></details><p className="plain-note">These patterns organize public evidence. They do not prove a repair was incomplete, identify a required service, or predict another closure.</p></>:<EmptyState/>}</section>;

  const handleSearchKey=(event:KeyboardEvent<HTMLInputElement>)=>{if(!searchResults.length){if(event.key==="Escape")setQuery("");return}if(event.key==="ArrowDown"){event.preventDefault();setActiveResult(value=>(value+1)%searchResults.length)}else if(event.key==="ArrowUp"){event.preventDefault();setActiveResult(value=>(value<=0?searchResults.length-1:value-1))}else if(event.key==="Enter"&&activeResult>=0){event.preventDefault();chooseCandidate(searchResults[activeResult].event)}else if(event.key==="Escape"){setQuery("");setActiveResult(-1)}};
  return <BookChapters unlockedThrough={unlockedThrough} comparisonReady={comparisonReady} comparisonBusy={peerSaved} noClosureJourney={selectedNeverClosed&&fetchState==="success"} onViewComparison={()=>{if(!comparisonReady)return;setLockedIds(draftCohort.map(e=>e.id));setPeerSaved(true);window.setTimeout(()=>{window.dispatchEvent(new CustomEvent("six-days-go-step",{detail:"timeline"}));setPeerSaved(false)},350)}}>
    <header className="book-chapter new-hero journey-landing" id="top"><div className="hero-mark" aria-hidden="true">6</div><div className="hero-content"><p className="live-label"><i/> NYC restaurant inspection analysis</p><p className="hero-overline">Find your restaurant record</p><h1>Understand the record.<br/><em>Plan what comes next.</em></h1><p>Six Days verifies the restaurant’s complete available history before showing closure or inspection information.</p>{!selected&&<div className={`finder hero-finder ${noMatches?"has-no-match":""}`}><label className="visually-hidden" htmlFor="restaurant-search">Restaurant name or CAMIS number</label><div className="search-row hero-two-line"><span>Search NYC Open Data</span><input id="restaurant-search" value={query} role="combobox" aria-expanded={searchResults.length>0} aria-controls="restaurant-results" aria-activedescendant={activeResult>=0?`restaurant-option-${activeResult}`:undefined} aria-autocomplete="list" onKeyDown={handleSearchKey} onChange={e=>{setQuery(e.target.value);setActiveResult(-1);setSelected(null);setSelectedNeverClosed(false)}} placeholder={searchFocused?"":"Restaurant name or CAMIS number"} onFocus={()=>setSearchFocused(true)} onBlur={()=>setSearchFocused(false)} autoComplete="off"/><b aria-hidden="true">→</b></div>{searchResults.length>0&&<ul className="search-results" id="restaurant-results" role="listbox" aria-label="Restaurant search results">{searchResults.map((item,index)=><li key={item.key} role="presentation"><button id={`restaurant-option-${index}`} role="option" aria-selected={index===activeResult} type="button" onMouseEnter={()=>setActiveResult(index)} onClick={()=>chooseCandidate(item.event)}><strong>{item.event.name}</strong><span>{item.event.borough} · inspection record available · CAMIS {item.event.camis}</span></button></li>)}</ul>}<p className="visually-hidden" aria-live="polite">{directoryState==="success"?`${searchResults.length} restaurant results available`:directoryState==="loading"?"Searching restaurant records":""}</p>{directoryState==="loading"&&query.trim().length>=2&&<p className="directory-searching" role="status">Checking NYC restaurant records…</p>}{directoryState==="error"&&<div className="no-search-match search-error" role="alert"><strong>Restaurant search is temporarily unavailable</strong><p>NYC Open Data could not be reached. This does not mean the restaurant is missing.</p><button type="button" onClick={()=>setRefreshKey(key=>key+1)}>Retry search</button></div>}{noMatches&&<div className="no-search-match" role="status"><strong>No restaurant record found</strong><p>Check the spelling or CAMIS number and try again.</p><button type="button" onClick={()=>{setQuery("");setSearchFocused(false)}}>Clear search</button></div>}</div>}<div className="hero-actions-row sample-only"><SampleLauncher /></div></div><div className="hero-proof"><strong>Confirm your inspection record</strong><span>Verify the complete four-year history</span><span>Plan with recorded evidence</span><small>Information only—not authorization to reopen</small></div></header>
    <section className="book-chapter owner-step" id="find"><Step n="01" title="Confirm my restaurant record" question="What did NYC record for this restaurant?" impact="Review your data"/><p className="step-intro">Six Days verifies this CAMIS history from {dateRange} before classifying the record.</p>{selected?<>{fetchState==="loading"&&<div className="verification-card" role="status"><span>LIVE VERIFICATION</span><h3>Checking this restaurant’s closure history…</h3><p>{selected.name} · CAMIS {selected.camis}</p></div>}{fetchState==="success"&&(selectedNeverClosed?<NeverClosedCard episode={selected} dateRange={dateRange}/>:<ClosureCard episode={selected}/>)}{fetchState==="empty"&&<div className="live-data-warning" role="alert"><span>NO HISTORY RETURNED</span><strong>Closure status could not be verified</strong><p>No inspection rows were returned for CAMIS {selected.camis} within {dateRange}.</p><button type="button" onClick={()=>setRefreshKey(key=>key+1)}>Try again →</button></div>}{fetchState==="error"&&<div className="live-data-warning" role="alert"><span>VERIFICATION UNAVAILABLE</span><strong>Closure status could not be verified because NYC Open Data is currently unavailable.</strong><p>No closure or no-closure conclusion has been made.</p><button type="button" onClick={()=>setRefreshKey(key=>key+1)}>Retry verification →</button></div>}{fetchState==="success"&&<p className="verification-meta">Verified {verifiedAt?fmt.format(new Date(verifiedAt)):"just now"} · analyzed period {dateRange}</p>}</>:<p className="journey-empty">Search for your restaurant on the opening screen to begin.</p>}</section>

    <section className="book-chapter owner-step context-step" id="compare">
      <Step n="02" title="Build my comparison" question={`Which evidence should Six Days compare with ${selected?.name??"my restaurant"}?`} impact="How would you like to build your comparison?"/>
      <p className="step-intro">Choose the complete match for this restaurant, or assemble your own comparison by selecting the parameters that matter to you.</p>
      {selected&&!selectedNeverClosed?<>
        <ComparisonPathChooser mode={comparisonMode} onChoose={mode=>{setComparisonMode(mode);setLockedIds([]);if(mode==="exact"){setSelectedCodes(selected.closure.codes.map(code=>code.code));setMatchTier("exact");setFilters(value=>({...value,scope:"city",boroughOverride:undefined,burdenTolerance:99}))}else{setSelectedCodes([]);setMatchTier(null);setFilters(value=>({...value,scope:"borough",boroughOverride:"",burdenTolerance:99}))}}}/>
        {comparisonMode==="custom"&&<CustomComparisonControls selected={selected} selectedCodes={selectedCodes} setSelectedCodes={setSelectedCodes} filters={filters} setFilters={setFilters} tier={matchTier} setTier={setMatchTier}/>}
      </>:selectedNeverClosed&&selected?<NeverClosedStep title="No closure comparison is needed" text={`${selected.name} was found in NYC Open Data, but no closure action was found in the available four-year dataset. Continue to review the available inspection information and data limitations.`}/>:<EmptyState/>}
    </section>

    <ComparisonResultsPage id="timeline" selected={selected} neverClosed={selectedNeverClosed} dateRange={dateRange} cohort={cohort} paths={boroughMap} mode={comparisonMode} tier={comparisonMode==="exact"?"exact":matchTier} filters={filters} codes={activeCodes} timeline={timeline} transitions={ownTransitionRows} recurrence={ownRecurrence} commonTimingRange={commonTimingRange}/>
    <section className="book-chapter owner-step monitor-step" id="monitor"><Step n="04" title={selectedNeverClosed?"Understand the data boundary":"Review my manager summary"} question={selectedNeverClosed?"What does this result prove—and what does it not prove?":"What does the evidence mean for my next decisions?"} impact={selectedNeverClosed?"Understand the limits of this inspection result":"Prepare my manager brief"}/><p className="step-intro">{selectedNeverClosed?"Use the exact coverage dates and live verification status when interpreting this result.":"Bring the verified closure, record-similarity group, timing evidence, and business assumptions together."}</p>{selected?selectedNeverClosed?<><NeverClosedManager episode={selected}/><FetchStateLabel state={fetchState} fetchedAt={verifiedAt||fetchedAt}/><div className="final-boundary"><strong>No closure action was found between {dateRange.replace("–"," and ")}.</strong><p>This does not prove the restaurant was never closed outside that period and does not establish current legal operating status.</p><a href="https://data.cityofnewyork.us/resource/43nn-pn8j" target="_blank" rel="noreferrer">View the NYC Open Data source →</a></div></>:<><ManagerSummary selected={selected} cohort={cohort} timeline={timeline} transitions={ownTransitionRows} recurrence={ownRecurrence}/><ManagerBrief selected={selected} cohort={cohort} timeline={timeline} dateRange={dateRange} verifiedAt={verifiedAt}/><FetchStateLabel state={fetchState} fetchedAt={verifiedAt||fetchedAt}/><LatestRecord closure={selected.closure} latest={latestRecords}/><div className="final-boundary"><strong>Six Days informs. The owner decides.</strong><p>This is a public-data snapshot, not continuous monitoring, legal operating status, a corrective-action checklist, or confirmation of reopening. Only NYC DOHMH authorizes reopening.</p></div></>:<EmptyState/>}</section>
  </BookChapters>
}

function Step({n,title,question,impact}:{n:string;title:string;question:string;impact:string}){if(n==="01")return <h2 data-page-heading tabIndex={-1}>{impact}</h2>;return <><div className="step-label"><span>STEP {n}</span><i>{title}</i></div><h2 data-page-heading tabIndex={-1}>{impact}</h2><p className="title-question"><strong>Question answered</strong><span>{question}</span></p></>}
function EmptyState(){return <p className="journey-empty">Choose a restaurant in Step 1 to calculate this section.</p>}
function ComparisonPathChooser({mode,onChoose}:{mode:"exact"|"custom"|null;onChoose:(mode:"exact"|"custom")=>void}){return <div className="comparison-paths" aria-label="Choose one comparison method"><article className={`comparison-path-card ${mode==="exact"?"selected":""}`}><span>OPTION 1</span><strong>Explore the complete match</strong><p>Use every violation recorded for this restaurant and find closures with the exact same complete code set across NYC.</p><button type="button" aria-pressed={mode==="exact"} onClick={()=>onChoose("exact")}><i aria-hidden="true"/>{mode==="exact"?"Option 1 selected":"Select Option 1"}</button></article><article className={`comparison-path-card ${mode==="custom"?"selected":""}`}><span>OPTION 2</span><strong>Build my own comparison</strong><p>Choose violation codes, geography, and match strength to assemble a transparent comparison set.</p><button type="button" aria-pressed={mode==="custom"} onClick={()=>onChoose("custom")}><i aria-hidden="true"/>{mode==="custom"?"Option 2 selected":"Select Option 2"}</button></article></div>}
function CustomComparisonControls({selected,selectedCodes,setSelectedCodes,filters,setFilters,tier,setTier}:{selected:ClosureEpisode;selectedCodes:string[];setSelectedCodes:(codes:string[])=>void;filters:CohortFilters;setFilters:(filters:CohortFilters)=>void;tier:MatchTier|null;setTier:(tier:MatchTier)=>void}){const toggle=(code:string)=>setSelectedCodes(selectedCodes.includes(code)?selectedCodes.filter(item=>item!==code):[...selectedCodes,code]);return <section className="custom-comparison" aria-label="Custom comparison parameters"><header><span>YOUR PARAMETERS</span><strong>{selectedCodes.length} of {selected.closure.codes.length} violation codes selected</strong></header><div className="custom-parameter-grid"><fieldset><legend>Violation codes</legend>{selected.closure.codes.map(code=><label key={code.code}><input type="checkbox" checked={selectedCodes.includes(code.code)} onChange={()=>toggle(code.code)}/><code>{code.code}</code><span>{code.description}</span></label>)}</fieldset><div><label className="parameter-select"><span>Geographic area</span><select value={filters.scope==="city"?"city":filters.boroughOverride||""} onChange={event=>setFilters({...filters,scope:event.target.value==="city"?"city":"borough",boroughOverride:event.target.value})}><option value="" disabled>Select an area</option><option value="city">All NYC boroughs</option>{["Bronx","Brooklyn","Manhattan","Queens","Staten Island"].map(borough=><option key={borough} value={borough}>{borough}</option>)}</select></label><div className="parameter-strength" role="group" aria-label="Match strength"><span>Match strength</span>{([{"id":"exact","title":"Exact","copy":"Only the selected codes"},{"id":"strong","title":"Strong","copy":"Most selected codes; all selected critical codes"},{"id":"broad","title":"Broad","copy":"At least half of the selected codes"}] as const).map(option=><button type="button" key={option.id} aria-pressed={tier===option.id} className={tier===option.id?"selected":""} onClick={()=>setTier(option.id)}><strong>{option.title}</strong><small>{option.copy}</small></button>)}</div></div></div><p className="custom-logic" aria-live="polite"><strong>Applied criteria:</strong> {selectedCodes.length} codes · {filters.scope==="city"?"All NYC":filters.boroughOverride||"area not selected"} · {tier??"strength not selected"} · {filters.periodYears}-year window · {filters.inspectionType?"same inspection type":"any inspection type"} · burden tolerance {filters.burdenTolerance} · selected episode excluded.</p></section>}
function ExactBenchmark({selected,matches,mode="exact",codes=selected.closure.codes.map(code=>code.code),tier="exact"}:{selected:ClosureEpisode;matches:ClosureEpisode[];mode?:"exact"|"custom";codes?:string[];tier?:MatchTier}){const median=(values:number[])=>{const sorted=[...values].sort((a,b)=>a-b);return sorted.length?(sorted.length%2?sorted[(sorted.length-1)/2]:(sorted[sorted.length/2-1]+sorted[sorted.length/2])/2):null};const critical=(episode:ClosureEpisode)=>episode.closure.codes.filter(code=>code.critical&&codes.includes(code.code)).length;const reopened=matches.filter(item=>item.reopening).length;const medianScore=median(matches.flatMap(item=>item.closure.score===null?[]:[item.closure.score]));const medianDays=median(matches.flatMap(item=>item.reopeningDays===null?[]:[item.reopeningDays]));const label=mode==="exact"?"COMPLETE EXACT-MATCH CHECK":"CUSTOM PARAMETER CHECK";const empty=mode==="exact"?"No complete match found":"No records match these parameters";return <section className="exact-benchmark" aria-label="Selected restaurant comparison result"><header><span>{label}</span><strong>{matches.length?`${matches.length} matching closure ${matches.length===1?"record":"records"} found`:empty}</strong><p>{mode==="exact"?matches.length?`Every benchmark record contains exactly the complete ${codes.length}-code set recorded for ${selected.name}.`:`No other qualifying NYC closure contains this exact complete ${codes.length}-code set.`:matches.length?`These records satisfy your ${tier} match rule for codes ${codes.join(", ")}.`:`Try changing the selected codes, geographic area, or match strength.`}</p></header><div className="benchmark-columns"><article><span>{mode==="exact"?"YOUR RESTAURANT":"YOUR SELECTED PARAMETERS"}</span><h3>{selected.name}</h3><dl><div><dt>Violation codes</dt><dd>{codes.join(", ")}</dd></div><div><dt>Selected critical flags</dt><dd>{selected.closure.codes.filter(code=>code.critical&&codes.includes(code.code)).length}</dd></div><div><dt>Inspection score</dt><dd>{selected.closure.score??"Not recorded"}</dd></div><div><dt>Match rule</dt><dd>{tier}</dd></div></dl></article><article className="benchmark-profile"><span>COMPARABLE PROFILE · AGGREGATED</span><h3>{matches.length?`${new Set(matches.map(item=>item.camis)).size} comparable restaurants`:"Comparison unavailable"}</h3>{matches.length?<dl><div><dt>Target codes</dt><dd>{codes.join(", ")}</dd></div><div><dt>Typical matching critical flags</dt><dd>{median(matches.map(critical))}</dd></div><div><dt>Median inspection score</dt><dd>{medianScore??"Not recorded"}</dd></div><div><dt>Reopening recorded</dt><dd>{reopened} of {matches.length} · {percent(reopened,matches.length)}</dd></div><div><dt>Median recorded interval</dt><dd>{medianDays===null?"Not available":`${medianDays} days`}</dd></div></dl>:<p className="benchmark-no-match">No result is being substituted. Adjust your parameters or choose the complete match path.</p>}</article></div><footer>This profile is calculated from public records matching the path and parameters shown above.</footer></section>}
function ViolationOutcomeTable({selected,rows,recurrence}:{selected:ClosureEpisode;rows:TransitionRow[];recurrence:ReturnType<typeof recurrenceAnalysis>}){const rowMap=new Map(rows.map(row=>[row.code,row]));const recurrenceMap=new Map(recurrence.codes.map(row=>[row.code,row.count]));const measured=selected.closure.codes.filter(code=>(rowMap.get(code.code)?.atClosure??0)>0);const absentInAll=measured.filter(code=>{const row=rowMap.get(code.code)!;return row.absent===row.atClosure}).length;return <section className="violation-outcomes organized" aria-label="Later public-record patterns for every selected violation"><header><span>REOPENING CHANGE</span><h3>{measured.length?`${absentInAll} of ${measured.length} violations were absent from every available reopening record`:`No reopening record was available for comparison`}</h3><p>“Absent” means a code did not appear in the next matched reopening record. It does not establish why the restaurant reopened.</p></header><div className="outcome-code-list">{selected.closure.codes.map(code=>{const row=rowMap.get(code.code);const absent=row&&row.atClosure?row.absent:0;const remained=row&&row.atClosure?row.remained:0;const primary=absent>=remained?"Absent at reopening":"Still recorded at reopening";const count=absent>=remained?absent:remained;return <article key={code.code}><div className="outcome-code"><code>{code.code}</code><span className={code.critical?"critical":""}>{code.critical?"Critical":"Not critical"}</span></div><p>{code.description}</p><div className={`outcome-result ${row&&row.atClosure?"measured":"unavailable"}`}><strong>{row&&row.atClosure?primary:"Not measurable"}</strong><small>{row&&row.atClosure?`${count} of ${row.atClosure} available reopening ${row.atClosure===1?"record":"records"}`:"No reopening evidence"}</small></div></article>})}</div><section className={`recurrence-summary ${recurrence.reclosed?"measured":"unavailable"}`}><div><span>LATER-CLOSURE CHECK</span><h3>{recurrence.reclosed?`${recurrence.reclosed} later ${recurrence.reclosed===1?"closure":"closures"} available`:`Recurrence cannot be measured for this group`}</h3><p>{recurrence.reclosed?"The results below show whether each original code appeared in those later closure records.":"None of the observable exact-match restaurants had a later closure record, so the data cannot show whether these violations recurred."}</p></div>{recurrence.reclosed&&<ul>{selected.closure.codes.map(code=>{const returned=recurrenceMap.get(code.code)??0;return <li key={code.code}><code>{code.code}</code><strong>{returned} of {recurrence.reclosed}</strong><span>later closures</span></li>})}</ul>}</section></section>}
function ComparisonResultsPage({selected,neverClosed,dateRange,cohort,paths,mode,tier,filters,codes,timeline,transitions,recurrence,commonTimingRange}:{id?:string;selected:ClosureEpisode|null;neverClosed:boolean;dateRange:string;cohort:ClosureEpisode[];paths:BoroughMapPath[];mode:"exact"|"custom"|null;tier:MatchTier|null;filters:CohortFilters;codes:string[];timeline:ReturnType<typeof timelineAnalysis>;transitions:TransitionRow[];recurrence:ReturnType<typeof recurrenceAnalysis>;commonTimingRange:{label:string;count:number}|null}){
  if(selected&&neverClosed)return <section className="book-chapter owner-step comparison-results-page" id="timeline"><Step n="02" title="Review inspection information" question="What is in the latest verified inspection record?" impact="Review the available inspection details"/><InspectionSnapshot event={selected.closure}/><NeverClosedStep title="Closure-based analysis is not available" text={`No closure or re-closure action was found for ${selected.name} between ${dateRange.replace("–"," and ")}. Without a closure event, Six Days does not calculate a reopening interval or closure comparison.`}/></section>;
  if(!selected||!mode)return <section className="book-chapter owner-step comparison-results-page" id="timeline"><Step n="03" title="Plan for closure length" question="How long should the business be prepared to remain closed?" impact="Plan for the days you may be closed"/><EmptyState/></section>;
  if(!cohort.length)return <section className="book-chapter owner-step comparison-results-page" id="timeline"><Step n="03" title="Plan for closure length" question="How long should the business be prepared to remain closed?" impact="Plan for the days you may be closed"/><p className="step-intro">No matching closure records were saved. Return to Step 2 and adjust the comparison.</p></section>;
  const median=(values:number[])=>{const sorted=[...values].sort((a,b)=>a-b);return sorted.length?(sorted.length%2?sorted[(sorted.length-1)/2]:(sorted[sorted.length/2-1]+sorted[sorted.length/2])/2):null};
  const uniqueRestaurants=new Set(cohort.map(item=>item.camis)).size;
  const sortedDays=[...timeline.values].sort((a,b)=>a-b);
  const percentile=(p:number)=>{if(!sortedDays.length)return null;const index=(sortedDays.length-1)*p;const lower=Math.floor(index);const upper=Math.ceil(index);return lower===upper?sortedDays[lower]:sortedDays[lower]+(sortedDays[upper]-sortedDays[lower])*(index-lower)};
  const rangeStart=sortedDays.length>=8?percentile(.25):sortedDays[0]??null;
  const rangeEnd=sortedDays.length>=8?percentile(.75):sortedDays[sortedDays.length-1]??null;
  const shortCases=timeline.values.filter(value=>value<=3).length;
  const workingCases=timeline.values.filter(value=>value>=4&&value<=14).length;
  const extendedCases=timeline.values.filter(value=>value>=15).length;
  const criticalCounts=cohort.map(item=>item.closure.codes.filter(code=>code.critical).length);
  const sharedCodes=codes.filter(code=>cohort.every(item=>item.closure.codes.some(candidate=>candidate.code===code)));
  const partialCodes=codes.filter(code=>!sharedCodes.includes(code));
  const laterIntervals=cohort.flatMap(item=>item.laterClosureDays===null?[]:[item.laterClosureDays]);
  const topRepeated=recurrence.codes[0];
  const rule=mode==="exact"?`Your restaurant was compared with NYC closures containing exactly the same complete ${codes.length}-code violation set.`:`Your restaurant was compared with ${tier??"selected"} matches using codes ${codes.join(", ")}.`;
  return <section className="book-chapter owner-step comparison-results-page" id="timeline">
    <Step n="03" title="Plan for closure length" question="How long should the business be prepared to remain closed?" impact="Plan for the days you may be closed"/>
    <section className="primary-planning-range" aria-labelledby="planning-range-heading">
      <div><span>PRIMARY PLANNING ANSWER</span><h3 id="planning-range-heading">How long should the business be prepared to remain closed?</h3><p>Use several historical scenarios from matching closure records—not one predicted reopening date.</p></div>
      <div className="range-answer"><span>{sortedDays.length>=8?"CENTRAL 50% OF RECORDED REOPENINGS":"LIMITED EVIDENCE · OBSERVED RANGE"}</span><strong>{rangeStart===null||rangeEnd===null?"Not available":`${Math.round(rangeStart)}–${Math.round(rangeEnd)} days`}</strong><p>{timeline.median===null?"Median unavailable":`Median: ${timeline.median} days`} · calculated from {timeline.matched} of {timeline.total} matching closures</p>{sortedDays.length>0&&sortedDays.length<8&&<SmallSampleDotPlot values={sortedDays}/>}</div>
      <div className="unmatched-answer"><strong>{timeline.total-timeline.matched}</strong><span>matching {timeline.total-timeline.matched===1?"record had":"records had"} no later reopening matched</span></div>
    </section>
    <section className="planning-scenario-results" aria-labelledby="planning-scenarios-heading"><header><span>HISTORICAL EVIDENCE SCENARIOS</span><h3 id="planning-scenarios-heading">Build the business plan around more than one recorded interval</h3><p>Intervals measure days between recorded closure and recorded reopening actions; they may not equal actual business downtime.</p></header><div><article><span>SHORT RECORDED INTERVAL</span><strong>0–3 days</strong><p>{shortCases} of {timeline.total} record-similarity closures · {percent(shortCases,timeline.total)}</p></article><article><span>WORKING RECORDED INTERVAL</span><strong>4–14 days</strong><p>{workingCases} of {timeline.total} record-similarity closures · {percent(workingCases,timeline.total)}</p></article><article className="extended"><span>EXTENDED RECORDED INTERVAL</span><strong>15+ days</strong><p>{extendedCases} of {timeline.total} record-similarity closures · {percent(extendedCases,timeline.total)}</p></article><article className="unmatched-scenario"><span>NO REOPENING MATCHED</span><strong>{timeline.unmatched}</strong><p>{timeline.unmatchedObservable15} old enough to observe day 15 · {timeline.unmatchedTooRecent15} too recent</p></article></div></section>
    <section className="planning-distribution" aria-labelledby="planning-distribution-heading"><header><span>WHEN REOPENING RECORDS APPEARED</span><h3 id="planning-distribution-heading">Complete timing distribution</h3></header><PlanningDistribution values={timeline.values} total={timeline.total}/></section>
    <section className="planning-checkpoints" aria-labelledby="planning-checkpoints-heading"><header><span>HOW MANY CASES STILL LACKED A REOPENING RECORD?</span><h3 id="planning-checkpoints-heading">Day 7, 14, and 30 planning checkpoints</h3></header><div>{timeline.thresholds.map(item=><article key={item.days}><span>AT DAY {item.days}</span>{item.eligible?<><strong>{item.without} of {item.eligible}</strong><p>{item.rate.toFixed(1)}% of eligible cases still lacked a reopening record</p></>:<><strong>Not measurable</strong><p>No matching closures were old enough to observe day {item.days}.</p></>}</article>)}</div><footer>Eligible means the closure occurred long enough ago to observe this checkpoint. “No reopening matched” does not mean the restaurant never reopened.</footer></section>
    <ScenarioCalculator timeline={timeline}/>
    <section className="planning-basis" aria-labelledby="planning-basis-heading"><header><span>WHAT THIS PLANNING RANGE IS BASED ON</span><h3 id="planning-basis-heading">The comparison-group evidence</h3></header><div><article><strong>{timeline.total}</strong><span>matching closure records</span></article><article><strong>{uniqueRestaurants}</strong><span>unique restaurants</span></article><article><strong>{timeline.matched}</strong><span>recorded reopenings</span></article><article><strong>{timeline.total-timeline.matched}</strong><span>without a matched reopening</span></article></div><p>{rule}</p></section>
    <div className="comparison-definition">
      <span>WHAT STEP 3 VISUALIZES</span>
      <h3>{cohort.length} closure records that matched {selected.name}</h3>
      <p>This page compares your selected closure with the records produced by the rule you chose in Step 2. The selected restaurant is context; the {cohort.length} matching records are the comparison group.</p>
    </div>
    <div className="comparison-flow" aria-label="How the Step 3 comparison was created">
      <article><span>1 · YOUR CLOSURE</span><strong>{selected.name}</strong><p>{selected.closure.date} · codes {codes.join(", ")}</p></article>
      <i aria-hidden="true">→</i>
      <article><span>2 · MATCHING RULE</span><strong>{mode==="exact"?"Same complete code set":`${tier??"Selected"} code match`}</strong><p>{mode==="exact"?"All NYC closure records":"The custom parameters saved in Step 2"}</p></article>
      <i aria-hidden="true">→</i>
      <article><span>3 · COMPARISON GROUP</span><strong>{cohort.length} matching records</strong><p>{uniqueRestaurants} unique restaurants</p></article>
    </div>
    <p className="comparison-rule"><strong>Comparison rule:</strong> {rule}</p>
    <div className="comparison-kpis" aria-label="Comparison summary">
      <article><span>MATCHING CLOSURE RECORDS</span><strong>{cohort.length}</strong><p>records in this comparison</p></article>
      <article><span>UNIQUE RESTAURANTS</span><strong>{uniqueRestaurants}</strong><p>distinct CAMIS numbers</p></article>
      <article><span>RECORDED REOPENINGS</span><strong>{timeline.matched} of {timeline.total}</strong><p>{percent(timeline.matched,timeline.total)} of matching records</p></article>
      <article><span>MEDIAN RECORDED TIME</span><strong>{timeline.median===null?"Not available":`${timeline.median} days`}</strong><p>historical interval, not a prediction</p></article>
    </div>
    <ComparisonPointMap paths={paths} episodes={cohort} selected={selected}/>
    <section className="comparison-split" aria-labelledby="restaurant-group-heading">
      <header><span>VIEW 2 · HOW DOES YOUR RECORD DIFFER?</span><h3 id="restaurant-group-heading">Your closure beside the comparison group</h3></header>
      <div><article><span>SELECTED RESTAURANT</span><h4>{selected.name}</h4><dl><div><dt>Closure date</dt><dd>{selected.closure.date}</dd></div><div><dt>Inspection score</dt><dd>{selected.closure.score??"Not recorded"}</dd></div><div><dt>Critical violations</dt><dd>{selected.closure.codes.filter(code=>code.critical).length}</dd></div><div><dt>Violation codes</dt><dd>{selected.closure.codes.map(code=>code.code).join(", ")}</dd></div><div><dt>Recorded reopening</dt><dd>{selected.reopening?.date??"Not matched"}</dd></div><div><dt>Second closure</dt><dd>{selected.laterClosure?.date??"Not matched"}</dd></div></dl></article><article><span>COMPARISON GROUP</span><h4>{cohort.length} matching records</h4><dl><div><dt>Median inspection score</dt><dd>{median(cohort.flatMap(item=>item.closure.score===null?[]:[item.closure.score]))??"Not recorded"}</dd></div><div><dt>Typical critical violations</dt><dd>{median(criticalCounts)??"Not available"}</dd></div><div><dt>Shared selected codes</dt><dd>{sharedCodes.length?sharedCodes.join(", "):"None shared by every record"}</dd></div><div><dt>Recorded reopenings</dt><dd>{timeline.matched} of {timeline.total} · {percent(timeline.matched,timeline.total)}</dd></div><div><dt>Median recorded interval</dt><dd>{timeline.median===null?"Not available":`${timeline.median} days`}</dd></div><div><dt>Later closure within observable year</dt><dd>{recurrence.reclosed} of {recurrence.eligible} · {percent(recurrence.reclosed,recurrence.eligible)}</dd></div></dl></article></div>
      <p className="comparison-meaning"><strong>Recorded fact:</strong> these values summarize the selected public record and the saved comparison group; they do not establish why outcomes differed.</p>
    </section>
    <section className="results-section timing-results" aria-labelledby="timing-distribution-heading"><header><span>SUPPORTING VIEW · WHAT IS THE FULL TIME RANGE?</span><h3 id="timing-distribution-heading">Recorded reopening time across the comparison group</h3></header><TimelineBars values={timeline.values}/><div className="timing-facts"><article><strong>{timeline.values.filter(value=>value<=3).length}</strong><span>fast cases · 0–3 days</span></article><article><strong>{timeline.median??"—"}</strong><span>median recorded days</span></article><article><strong>{commonTimingRange?.label??"Not available"}</strong><span>most common range</span></article><article><strong>{timeline.values.filter(value=>value>14).length}</strong><span>longer cases · over 14 days</span></article><article><strong>{timeline.total-timeline.matched}</strong><span>without a matched reopening</span></article></div><p className="comparison-meaning"><strong>Planning implication:</strong> use the full observed range when planning cash, staffing, inventory, and customer communication—not a single predicted date.</p></section>
    <section className="results-section violation-results" aria-labelledby="violation-comparison-heading"><header><span>3 · WHICH VIOLATIONS WERE COMPARED?</span><h3 id="violation-comparison-heading">Violations recorded across the matching restaurants</h3></header><div className="violation-matrix" role="table" aria-label="Selected violation codes across matching records"><div className="violation-matrix-head" role="row"><span role="columnheader">Code and description</span><span role="columnheader">Critical</span><span role="columnheader">At closure</span><span role="columnheader">Still recorded at reopening</span><span role="columnheader">Recorded in later closure</span></div>{selected.closure.codes.map(code=>{const atClosure=cohort.filter(item=>item.closure.codes.some(candidate=>candidate.code===code.code)).length;const transition=transitions.find(row=>row.code===code.code);const returned=recurrence.codes.find(row=>row.code===code.code)?.count??0;return <div className="violation-matrix-row" role="row" key={code.code}><span role="cell"><code>{code.code}</code><small>{code.description}</small></span><span role="cell">{code.critical?"Critical":"Not critical"}</span><span role="cell">{atClosure} of {cohort.length}</span><span role="cell">{transition?.remained??0} of {transition?.atClosure??0}</span><span role="cell">{returned} of {recurrence.reclosed}</span></div>})}</div><p className="comparison-meaning"><strong>Comparison-group pattern:</strong> {sharedCodes.length?`${sharedCodes.join(", ")} ${sharedCodes.length===1?"appears":"appear"} in every matched closure.`:"No selected code appears in every matched closure."} {partialCodes.length?`${partialCodes.join(", ")} ${partialCodes.length===1?"appears":"appear"} only in part of the group.`:""}</p></section>
    <section className="results-section later-closure-results" aria-labelledby="later-closure-heading"><header><span>VIEW 5 · WERE MATCHES CLOSED AGAIN?</span><h3 id="later-closure-heading">Later closures in the comparison group</h3></header><div className="later-closure-grid"><article><span>RESTAURANTS WITH A LATER CLOSURE</span><strong>{recurrence.reclosed} of {recurrence.eligible}</strong><p>{percent(recurrence.reclosed,recurrence.eligible)} among records observable for one year</p></article><article><span>TYPICAL INTERVAL</span><strong>{median(laterIntervals)===null?"Not available":`${median(laterIntervals)} days`}</strong><p>from recorded reopening to a later closure</p></article><article><span>MOST REPEATED ORIGINAL CODE</span><strong>{topRepeated?.code??"Not available"}</strong><p>{topRepeated?`${topRepeated.count} of ${recurrence.reclosed} later closures`:"No repeated original code measured"}</p></article><article><span>SELECTED RESTAURANT</span><strong>{selected.laterClosure?"Later closure recorded":"No later closure matched"}</strong><p>{selected.laterClosure?`${selected.laterClosure.date} · ${selected.laterClosureDays??"—"} days after reopening`:"Available dataset record"}</p></article></div><p className="comparison-meaning"><strong>Recorded fact:</strong> a later closure and a repeated violation can occur in the same public record, but this comparison does not establish causation.</p></section>
    <ViolationTimingEvidence selected={selected} cohort={cohort} transitions={transitions} recurrence={recurrence}/>
    <details className="other-violation-evidence"><summary><span>OTHER CODES FIRST RECORDED AT REOPENING</span><strong>View secondary evidence</strong><b>+</b></summary><div>{transitions.filter(row=>!codes.includes(row.code)&&row.appeared>0).sort((a,b)=>b.appeared-a.appeared).slice(0,8).map(row=><article key={row.code}><code>{row.code}</code><span>{row.description}</span><strong>{row.appeared} of {timeline.matched}</strong></article>)}</div><p>These codes were not part of the selected closure-code set. Their appearance does not establish a cause or corrective requirement.</p></details>
    <details className="match-method-details"><summary><span>WHY THESE RECORDS WERE CONSIDERED COMPARABLE</span><strong>View comparison method</strong><b>+</b></summary><div><dl><div><dt>Match method</dt><dd>{mode==="exact"?"Complete exact match":"Custom comparison"}</dd></div><div><dt>Geography</dt><dd>{filters.scope==="city"?"All NYC":filters.boroughOverride||selected.borough}</dd></div><div><dt>Match strength</dt><dd>{tier??"Not selected"}</dd></div><div><dt>Shared codes</dt><dd>{sharedCodes.length?sharedCodes.join(", "):"No code shared by every record"}</dd></div></dl><div className="method-code-chips">{codes.map(code=><code key={code}>{code}</code>)}</div></div></details>
    <div className="comparison-boundary"><strong>How to use this page</strong><p>Separate recorded facts from group patterns and planning implications. Only NYC DOHMH determines legal reopening status; Six Days does not provide reopening instructions or predict an exact date.</p></div>
  </section>
}

function SmallSampleDotPlot({values}:{values:number[]}){const max=Math.max(1,...values);return <figure className="small-sample-dots" aria-label={`Every observed recorded interval: ${values.join(", ")} days`}><div>{values.map((value,index)=><i key={`${value}-${index}`} style={{left:`${value/max*100}%`}}><span>{value}</span></i>)}</div><figcaption>Every recorded interval is shown · minimum {values[0]} days · maximum {values[values.length-1]} days</figcaption></figure>}

function PlanningDistribution({values,total}:{values:number[];total:number}){const buckets=[["0–3 days",0,3],["4–7 days",4,7],["8–14 days",8,14],["15–30 days",15,30],["31+ days",31,Infinity]] as const;const rows=buckets.map(([label,min,max])=>({label,count:values.filter(value=>value>=min&&value<=max).length}));const unmatched=total-values.length;return <div className="planning-distribution-bars" aria-label="Recorded reopening intervals across all matching closure records">{rows.map(row=><article key={row.label}><span>{row.label}</span><i><b style={{width:`${total?row.count/total*100:0}%`}}/></i><strong>{row.count} of {total} · {percent(row.count,total)}</strong></article>)}<article className="unmatched"><span>No reopening matched</span><i><b style={{width:`${total?unmatched/total*100:0}%`}}/></i><strong>{unmatched} of {total} · {percent(unmatched,total)}</strong></article></div>}

function ViolationTimingEvidence({selected,cohort,transitions,recurrence}:{selected:ClosureEpisode;cohort:ClosureEpisode[];transitions:TransitionRow[];recurrence:ReturnType<typeof recurrenceAnalysis>}){const median=(values:number[])=>{const sorted=[...values].sort((a,b)=>a-b);return sorted.length?(sorted.length%2?sorted[(sorted.length-1)/2]:(sorted[sorted.length/2-1]+sorted[sorted.length/2])/2):null};return <section className="violation-timing-evidence" aria-labelledby="violation-timing-heading"><header><span>RECORDED CLOSURE OUTCOMES BY CODE</span><h3 id="violation-timing-heading">Closure outcomes among records containing each code</h3><p>These are restaurant-level closure-to-reopening intervals, not the time required to correct an individual violation.</p></header><div>{selected.closure.codes.map(code=>{const containing=cohort.filter(item=>item.closure.codes.some(candidate=>candidate.code===code.code));const values=containing.flatMap(item=>item.reopeningDays===null?[]:[item.reopeningDays]);const sorted=[...values].sort((a,b)=>a-b);const row=transitions.find(item=>item.code===code.code);const repeated=recurrence.codes.find(item=>item.code===code.code)?.count??0;return <article key={code.code}><div className="violation-timing-code"><code>{code.code}</code><span className={code.critical?"critical":""}>{code.critical?"Critical":"Not critical"}</span></div><p>{code.description}</p><dl><div><dt>Restaurant-level median recorded interval</dt><dd>{values.length?`${median(values)} days`:"Not available"}</dd></div><div><dt>Observed range</dt><dd>{values.length?`${sorted[0]}–${sorted[sorted.length-1]} days`:"Not available"}</dd></div><div><dt>Reopening evidence</dt><dd>{values.length} of {containing.length} records</dd></div><div><dt>Absent at reopening</dt><dd>{row?.atClosure?`${row.absent} of ${row.atClosure}`:"Not measurable"}</dd></div><div><dt>Still recorded at reopening</dt><dd>{row?.atClosure?`${row.remained} of ${row.atClosure}`:"Not measurable"}</dd></div><div><dt>Recorded in a later closure</dt><dd>{recurrence.reclosed?`${repeated} of ${recurrence.reclosed}`:"Not measurable—no later closures"}</dd></div></dl></article>})}</div><footer>These are public-record associations, not correction times or proof that a violation caused reopening or a later closure.</footer></section>}

function ComparisonPointMap({paths,episodes,selected}:{paths:BoroughMapPath[];episodes:ClosureEpisode[];selected:ClosureEpisode}){
  const [focusedId,setFocusedId]=useState<string|null>(episodes[0]?.id??null);
  const focused=episodes.find(item=>item.id===focusedId)??null;
  const projection=paths[0]?.projection;
  const point=(longitude:number,latitude:number)=>projection?{x:projection.offsetX+(longitude-projection.minLon)*projection.scale,y:projection.offsetY+(projection.maxLat-latitude)*projection.scale}:{x:0,y:0};
  const plotted=episodes.filter(item=>item.latitude!==null&&item.longitude!==null);
  const clusters=[...plotted.reduce((map,item)=>{const key=`${item.latitude!.toFixed(4)}|${item.longitude!.toFixed(4)}`;const current=map.get(key)??[];current.push(item);map.set(key,current);return map},new Map<string,ClosureEpisode[]>()).entries()].map(([key,items])=>({key,items,location:point(items[0].longitude!,items[0].latitude!)}));
  const missing=episodes.length-plotted.length;
  const selectedPoint=selected.latitude!==null&&selected.longitude!==null?point(selected.longitude,selected.latitude):null;
  return <figure className="comparison-map">
    <header><div><span>GEOGRAPHIC CONTEXT</span><h3>Where the matching restaurants are located</h3><p>Every dark circle is one closure record in the record-similarity group. The square is {selected.name}, shown only as a reference point.</p><p>{plotted.length} of {episodes.length} matching records are shown. {missing} {missing===1?"record lacks":"records lack"} coordinates.</p></div><div className="map-symbols" aria-label="Map legend"><span><i className="selected-symbol"/>Your restaurant</span><span><i className="match-symbol"/>Matching record</span><span><i className="focus-symbol"/>Selected match</span></div></header>
    <div className="comparison-map-layout"><div className="comparison-map-stage"><svg viewBox="0 0 720 430" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><title>Locations of closure records in the comparison</title>{paths.map(path=><path key={path.name} d={path.path} fill="#eeeeef" fillRule="evenodd"/>)}{clusters.map(cluster=>{const isFocused=cluster.items.some(item=>item.id===focusedId);return <g key={cluster.key} className={isFocused?"focused":""}><circle cx={cluster.location.x} cy={cluster.location.y} r={isFocused?11:cluster.items.length>1?8:5}/>{cluster.items.length>1&&<text x={cluster.location.x} y={cluster.location.y+3}>{cluster.items.length}</text>}</g>})}{selectedPoint&&<rect x={selectedPoint.x-8} y={selectedPoint.y-8} width="16" height="16"/>}</svg>{focused&&<div className="comparison-map-inspector" aria-live="polite"><span>SELECTED MATCHING RECORD</span><strong>{focused.name}</strong><p>{focused.borough} · closed {focused.closure.date} · score {focused.closure.score??"not recorded"}</p><p>Codes: {focused.closure.codes.map(code=>code.code).join(", ")||"none recorded"}</p><b>{focused.reopening?`Recorded reopening ${focused.reopening.date} · ${focused.reopeningDays} days`:"Recorded reopening: Not matched"}</b></div>}</div><div className="comparison-map-list"><span>THE {episodes.length} MATCHING RECORDS · ACCESSIBLE MAP CONTROLS</span><small>{clusters.length} mapped locations; numbered markers contain multiple closure records.</small><div>{episodes.map(item=><button type="button" key={item.id} className={item.id===focusedId?"active":""} aria-pressed={item.id===focusedId} onClick={()=>setFocusedId(item.id)}><strong>{item.name}</strong><small>{item.borough} · {item.closure.date} · {item.reopeningDays===null?"reopening not matched":`${item.reopeningDays} recorded days`}</small></button>)}</div></div></div>
    <figcaption>Location provides context only; it does not explain reopening time.</figcaption>
  </figure>
}

function ScenarioCalculator({timeline}:{timeline:ReturnType<typeof timelineAnalysis>}){const [fixed,setFixed]=useState(0);const [labor,setLabor]=useState(0);const [inventory,setInventory]=useState(0);const [margin,setMargin]=useState(0);const daily=Math.max(0,fixed)+Math.max(0,labor)+Math.max(0,margin);const money=(value:number)=>new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",maximumFractionDigits:0}).format(value);const scenarios=[{label:"Short",days:3},{label:"Working",days:14},{label:"Extended",days:Math.max(30,Math.ceil(timeline.values.at(-1)??30))}];return <section className="scenario-calculator" aria-labelledby="scenario-calculator-heading"><header><span>OPTIONAL OWNER-ENTERED PLANNING ESTIMATE</span><h3 id="scenario-calculator-heading">Estimate financial exposure across the evidence scenarios</h3><p>These values come from you—not NYC data—and are planning estimates, not financial or reopening advice.</p></header><div className="scenario-inputs"><label><span>Daily fixed operating costs</span><input type="number" min="0" inputMode="decimal" value={fixed||""} onChange={event=>setFixed(Number(event.target.value)||0)}/></label><label><span>Scheduled daily labor exposure</span><input type="number" min="0" inputMode="decimal" value={labor||""} onChange={event=>setLabor(Number(event.target.value)||0)}/></label><label><span>Perishable inventory exposure</span><input type="number" min="0" inputMode="decimal" value={inventory||""} onChange={event=>setInventory(Number(event.target.value)||0)}/></label><label><span>Optional daily lost contribution margin</span><input type="number" min="0" inputMode="decimal" value={margin||""} onChange={event=>setMargin(Number(event.target.value)||0)}/></label></div><div className="scenario-outputs">{scenarios.map(item=><article key={item.label}><span>{item.label} · {item.days} days</span><strong>{money(daily*item.days+Math.max(0,inventory))}</strong><p>Daily exposure × {item.days}, plus inventory entered above</p></article>)}</div></section>}

function ManagerBrief({selected,cohort,timeline,dateRange,verifiedAt}:{selected:ClosureEpisode;cohort:ClosureEpisode[];timeline:ReturnType<typeof timelineAnalysis>;dateRange:string;verifiedAt:string}){return <section className="manager-brief" aria-labelledby="manager-brief-heading"><header><div><span>PRINTABLE ONE-PAGE SUMMARY</span><h3 id="manager-brief-heading">Manager brief</h3></div><button type="button" onClick={()=>window.print()}>Print brief</button></header><dl><div><dt>Restaurant</dt><dd>{selected.name} · CAMIS {selected.camis}</dd></div><div><dt>Selected closure</dt><dd>{selected.closure.date} · {selected.closure.action}</dd></div><div><dt>Analyzed period</dt><dd>{dateRange}</dd></div><div><dt>Live verification</dt><dd>{verifiedAt?fmt.format(new Date(verifiedAt)):"Not recorded"}</dd></div><div><dt>Record-similarity group</dt><dd>{cohort.length} closure records · {timeline.matched} recorded reopenings</dd></div><div><dt>Unmatched status</dt><dd>{timeline.unmatched} unmatched · {timeline.unmatchedTooRecent15} too recent to evaluate at day 15</dd></div><div><dt>Questions to verify</dt><dd>Confirm current status, required next inspection, staffing assumptions, inventory exposure, and cash coverage with the appropriate advisers.</dd></div></dl><p>Source: NYC Restaurant Inspection Results. Historical public-record intervals are not legal authorization, operating status, or a predicted reopening date.</p></section>}

function ManagerSummary({selected,cohort,timeline,transitions,recurrence}:{selected:ClosureEpisode;cohort:ClosureEpisode[];timeline:ReturnType<typeof timelineAnalysis>;transitions:TransitionRow[];recurrence:ReturnType<typeof recurrenceAnalysis>}){const priority=[...transitions].filter(row=>row.atClosure>=3).sort((a,b)=>(b.remained/b.atClosure)-(a.remained/a.atClosure))[0];return <section className="manager-summary" aria-label="Manager evidence summary"><div className="manager-summary-head"><span>YOUR NEXT DECISIONS</span><h3>{selected.name}</h3><p>Use the evidence from the journey without treating it as a reopening checklist.</p></div><div className="manager-summary-grid"><article><span>01 · CONFIRM THE RECORD</span><strong>Review Step 1</strong><p>Use the official closure descriptions to prepare the questions you need answered by DOHMH or a qualified adviser.</p><small>Your selected closure record remains the source.</small></article><article><span>02 · PREPARE THE BUSINESS</span><strong>Use the full range</strong><p>Plan cash, staffing, inventory, supplier, and customer decisions for more than one historical evidence scenario.</p><small>Step 3 contains recorded intervals; it is not a predicted date.</small></article><article><span>03 · VERIFY CLOSELY</span><strong>{priority?.code??"Insufficient evidence to rank reliably"}</strong><p>{priority?`${priority.remained} of ${priority.atClosure} reopening records still contained ${priority.code}. Review the denominator and description in Step 3.`:"No code met the minimum evidence count of three reopening records."}</p><small>{recurrence.reclosed?"Later-closure evidence is included in Step 3.":"No measurable later-closure signal was available."}</small></article></div><p className="manager-summary-source">Uses the record-similarity group selected in Step 2. Only DOHMH determines legal reopening status.</p></section>}
function OutcomeFlow({total,reopened,eligible,reclosed}:{total:number;reopened:number;eligible:number;reclosed:number}){const stages=[{value:total,label:"Retained episodes",detail:"Sharing selected criteria"},{value:reopened,label:"Reopening matched",detail:percent(reopened,total)},{value:eligible,label:"Observable follow-up",detail:"At least 365 days"},{value:reclosed,label:"Later closure recorded",detail:percent(reclosed,eligible)}];return <div className="outcome-flow" aria-label="Recorded outcomes for the retained peer set">{stages.map((stage,i)=><div className="outcome-stage" key={stage.label}><article><span>0{i+1}</span><strong>{stage.value}</strong><h3>{stage.label}</h3><p>{stage.detail}</p></article>{i<stages.length-1&&<i aria-hidden="true">→</i>}</div>)}</div>}
function RecurringCodes({recurrence,cohort}:{recurrence:ReturnType<typeof recurrenceAnalysis>;cohort:ClosureEpisode[]}){const allReturned=recurrence.codes.length>1&&recurrence.codes.every(row=>row.rate===100);return <div className="embedded-repeat"><div className="repeat-codes-heading"><span>ORIGINAL CODES RECORDED AGAIN AT A LATER CLOSURE</span><h3>{recurrence.codes.length?allReturned?`All ${recurrence.codes.length} recurring codes appeared in every qualifying later-closure episode`:`${recurrence.codes.length} recurring ${recurrence.codes.length===1?"code":"codes"} found`:"No recurring original codes found"}</h3></div>{recurrence.codes.length?(allReturned?<div className="all-returned"><div><strong>100%</strong><p>Each code below appeared in every qualifying later-closure episode.</p></div><ul>{recurrence.codes.slice(0,8).map(row=><li key={row.code}><code>{row.code}</code><span>{descriptionFor(cohort,row.code)}</span></li>)}</ul></div>:<div className="repeat-grid">{recurrence.codes.slice(0,6).map((row,i)=><article key={row.code}><span>0{i+1}</span><code>{row.code}</code><h3>{descriptionFor(cohort,row.code)}</h3><strong>{row.rate.toFixed(0)}%</strong><p>Recorded again in {row.count} of {recurrence.reclosed} later-closure episodes</p></article>)}</div>):<div className="repeat-empty"><strong>{recurrence.reclosed?"The later closures involved different recorded codes.":"No later closure was matched."}</strong><p>{recurrence.reclosed?`The ${recurrence.reclosed} later-closure episodes did not repeat an original code.`:"No eligible episode in this peer set had a later recorded closure within 365 observable days."}</p></div>}<p className="plain-note">This analysis now includes both “closed” and “re-closed” DOHMH actions. It remains observational and does not predict another closure or identify a corrective action.</p></div>}
function ClosureCard({episode}:{episode:ClosureEpisode}){return <div className="record-card"><div className="record-top"><div><span>OFFICIAL RECORDED CLOSURE</span><h3>{episode.name}</h3><p>{episode.borough} · CAMIS {episode.camis}</p></div><strong className={episode.reopening?"status-open":"status-closed"}>{episode.reopening?"REOPENING RECORDED":"NO REOPENING MATCHED"}</strong></div><div className="record-facts"><article><span>Closure</span><strong>{episode.closure.date}</strong></article><article><span>Score</span><strong>{episode.closure.score??"—"}</strong></article><article><span>Recorded reopening</span><strong>{episode.reopening?.date??"Not matched"}</strong></article><article><span>Second closure</span><strong>{episode.laterClosure?.date??"Not matched"}</strong></article></div><p className="record-summary">The available record shows a closure on {episode.closure.date}{episode.reopening?`, followed by a recorded reopening ${episode.reopeningDays} ${episode.reopeningDays===1?"day":"days"} later`:" with no later reopening matched"}{episode.laterClosure?`, and another closure recorded on ${episode.laterClosure.date}`:"; no second closure was matched"}.</p><h4>Violations recorded at closure</h4><div className="code-list">{episode.closure.codes.map(c=><article key={c.code}><code>{c.code}</code><div><span className={c.critical?"critical-tag":"noncritical-tag"}>{c.critical?"Critical":"Not critical"}</span><p>{c.description}</p></div></article>)}</div><p className="record-boundary">Critical status is reproduced from the NYC Open Data critical_flag field. This does not determine required corrections or authorize reopening.</p></div>}
function NeverClosedStep({title,text}:{title:string;text:string}){return <section className="never-closed-message" role="status"><span>NO CLOSURE RECORDED</span><h3>{title}</h3><p>{text}</p></section>}
function NeverClosedCard({episode,dateRange}:{episode:ClosureEpisode;dateRange:string}){return <div className="record-card never-closed-card"><div className="record-top"><div><span>VERIFIED NYC INSPECTION RECORD</span><h3>{episode.name}</h3><p>{episode.borough} · CAMIS {episode.camis}{episode.address?` · ${episode.address}`:""}</p></div><strong className="no-closure-badge">NO CLOSURE ACTION FOUND</strong></div><div className="record-facts"><article><span>Latest inspection</span><strong>{episode.closure.date}</strong></article><article><span>Score</span><strong>{episode.closure.score??"Not recorded"}</strong></article><article><span>Grade</span><strong>{episode.closure.grade??"Not recorded"}</strong></article><article><span>Analyzed period</span><strong>{dateRange}</strong></article></div><p className="record-summary">No DOHMH closure or re-closure action was found between {dateRange.replace("–"," and ")}. The latest available row is an inspection record, not a closure record.</p><h4>Violations on the latest available inspection</h4><div className="code-list">{episode.closure.codes.length?episode.closure.codes.map(c=><article key={c.code}><code>{c.code}</code><div><span className={c.critical?"critical-tag":"noncritical-tag"}>{c.critical?"Critical":"Not critical"}</span><p>{c.description}</p></div></article>):<p>No violation codes were included on this inspection row.</p>}</div><p className="record-boundary">This does not prove that the restaurant was never closed outside the analyzed period and does not confirm current legal operating status.</p></div>}
function InspectionSnapshot({event}:{event:InspectionEvent}){return <section className="inspection-snapshot" aria-label="Latest available inspection information"><header><span>LATEST AVAILABLE INSPECTION</span><h3>{event.name}</h3><p>{event.address}{event.zipcode?` · ${event.zipcode}`:""} · CAMIS {event.camis}</p></header><div><article><span>Inspection date</span><strong>{event.date}</strong></article><article><span>Recorded action</span><strong>{event.action||"Not recorded"}</strong></article><article><span>Score</span><strong>{event.score??"Not recorded"}</strong></article><article><span>Grade</span><strong>{event.grade??"Not recorded"}</strong></article></div><h4>Violation information on this inspection</h4><ul>{event.codes.length?event.codes.map(code=><li key={code.code}><code>{code.code}</code><span>{code.description}</span><strong>{code.critical?"Critical":"Not critical"}</strong></li>):<li><span>No violation codes were included on this inspection row.</span></li>}</ul></section>}
function NeverClosedManager({episode}:{episode:ClosureEpisode}){return <section className="manager-summary never-closed-manager" aria-label="No-closure manager summary"><div className="manager-summary-head"><span>AVAILABLE RECORD SUMMARY</span><h3>{episode.name}</h3><p>This restaurant was found, but no closure action was found in the available four-year dataset.</p></div><div className="manager-summary-grid"><article><span>01 · RECORDED FACT</span><strong>Inspection record found</strong><p>The latest available inspection is dated {episode.closure.date}.</p></article><article><span>02 · NOT AVAILABLE</span><strong>No closure timeline</strong><p>Reopening duration and closure-peer comparisons cannot be calculated without a recorded closure event.</p></article><article><span>03 · DATA LIMIT</span><strong>Four-year window</strong><p>The result does not rule out a closure before the analyzed period or establish current operating status.</p></article></div></section>}
function PeerSetMap({paths,episodes}:{paths:BoroughMapPath[];episodes:ClosureEpisode[]}){const [focused,setFocused]=useState("All NYC");const boroughs=["Bronx","Brooklyn","Manhattan","Queens","Staten Island"];const count=(borough:string)=>episodes.filter(e=>e.borough===borough).length;const activeCount=focused==="All NYC"?episodes.length:count(focused);const max=Math.max(1,...boroughs.map(count));return <figure className="peer-set-map"><div><span>GEOGRAPHIC DISTRIBUTION</span><strong>{focused}</strong><p>{activeCount} of {episodes.length} episodes · {percent(activeCount,episodes.length)}</p><ul>{boroughs.map(borough=><li key={borough}><button type="button" className={focused===borough?"active":""} onMouseEnter={()=>setFocused(borough)} onFocus={()=>setFocused(borough)} onClick={()=>setFocused(borough)}><span><strong>{count(borough)}</strong><small>{borough}</small></span><i style={{width:`${count(borough)/max*100}%`}}/></button></li>)}</ul></div><svg viewBox="0 0 720 430" preserveAspectRatio="xMidYMid meet" role="img" aria-label={`Borough distribution for ${episodes.length} proposed peer closure episodes`}>{paths.map(path=>{const boroughCount=count(path.name);const intensity=boroughCount/max;return <path key={path.name} d={path.path} fill={`rgba(177,131,36,${.18+intensity*.82})`} fillRule="evenodd" role="button" tabIndex={0} aria-label={`${path.name}: ${boroughCount} episodes`} className={focused===path.name?"active":""} onMouseEnter={()=>setFocused(path.name)} onFocus={()=>setFocused(path.name)} onClick={()=>setFocused(path.name)}/>})}</svg><figcaption>Choose or point to a borough to see its share. Geography is descriptive and does not explain outcomes.</figcaption></figure>}
function JourneyMap({paths,episodes,allMatches,selected,activeArea,onSelectArea}:{paths:BoroughMapPath[];episodes:ClosureEpisode[];allMatches:ClosureEpisode[];selected:ClosureEpisode;activeArea:string;onSelectArea:(area:string)=>void}){
  const [focused,setFocused]=useState<ClosureEpisode|null>(null);
  const areas=["All NYC","Bronx","Brooklyn","Manhattan","Queens","Staten Island"];
  const counts=new Map<string,number>();
  allMatches.forEach(e=>counts.set(e.borough,(counts.get(e.borough)??0)+1));
  const projection=paths[0]?.projection;
  const point=(longitude:number,latitude:number)=>projection?{x:projection.offsetX+(longitude-projection.minLon)*projection.scale,y:projection.offsetY+(projection.maxLat-latitude)*projection.scale}:{x:0,y:0};
  const selectedPoint=selected.latitude!==null&&selected.longitude!==null?point(selected.longitude,selected.latitude):null;
  return <figure className="journey-map"><div className="map-heading"><div><span>INTERACTIVE AREA MAP</span><figcaption>Choose where to compare this closure</figcaption><p>Select an area, then point to any gold marker to inspect that restaurant’s recorded outcome.</p></div><strong>{activeArea}</strong></div><div className="map-layout"><div className="map-area-buttons" aria-label="Choose comparison area">{areas.map(area=><button type="button" key={area} className={activeArea===area?"active":""} onClick={()=>{setFocused(null);onSelectArea(area)}}><span>{area}</span><b>{area==="All NYC"?allMatches.length:counts.get(area)??0}</b></button>)}</div><div className="map-stage"><svg viewBox="0 0 720 430" preserveAspectRatio="xMidYMid meet" role="img" aria-label={`Map of ${activeArea} showing ${episodes.length} comparable closure records`}>{paths.map(p=><path key={p.name} d={p.path} fill="#d8cdb8" fillRule="evenodd"/>)}{episodes.filter(e=>e.latitude!==null&&e.longitude!==null).map(e=>{const p=point(e.longitude!,e.latitude!);return <circle key={e.id} cx={p.x} cy={p.y} r={focused?.id===e.id?8:5} role="button" tabIndex={0} aria-label={`${e.name}, closed ${e.closure.date}${e.reopening?`, reopened after ${e.reopeningDays} days`:`, no reopening record matched`}`} onMouseEnter={()=>setFocused(e)} onFocus={()=>setFocused(e)} onClick={()=>setFocused(e)}/>})}{selectedPoint&&<rect x={selectedPoint.x-8} y={selectedPoint.y-8} width="16" height="16"/>}</svg><div className="map-inspector" aria-live="polite">{focused?<><span>COMPARABLE RESTAURANT</span><strong>{focused.name}</strong><p>{focused.borough} · closed {focused.closure.date}</p><b>{focused.reopening?`${focused.reopeningDays} recorded days to reopening`:"No reopening record matched"}</b></>:<><span>EXPLORE THE DATA</span><strong>{episodes.length} comparable closures</strong><p>Hover, focus, or tap a gold marker for its recorded outcome.</p></>}</div></div></div><p className="map-legend"><i/> Comparable closure <b/> Selected restaurant <span>{episodes.filter(e=>e.latitude===null||e.longitude===null).length} records lack coordinates</span></p></figure>}

type TransitionRow={code:string;description:string;atClosure:number;absent:number;remained:number;appeared:number};
function transitionRows(episodes:ClosureEpisode[]){const eligible=episodes.filter(e=>e.reopening);const rows=new Map<string,TransitionRow>();eligible.forEach(e=>{const before=new Map(e.closure.codes.map(c=>[c.code,c]));const after=new Map(e.reopening!.codes.map(c=>[c.code,c]));before.forEach((c,code)=>{const r=rows.get(code)??{code,description:c.description,atClosure:0,absent:0,remained:0,appeared:0};r.atClosure++;if(after.has(code))r.remained++;else r.absent++;rows.set(code,r)});after.forEach((c,code)=>{if(before.has(code))return;const r=rows.get(code)??{code,description:c.description,atClosure:0,absent:0,remained:0,appeared:0};r.appeared++;rows.set(code,r)})});const list=[...rows.values()];return {eligible:eligible.length,rows:list,topRemained:[...list].sort((a,b)=>b.remained-a.remained)[0],topAppeared:[...list].sort((a,b)=>b.appeared-a.appeared)[0]}}
function TransitionList({title,rows,value}:{title:string;rows:TransitionRow[];value:(row:TransitionRow)=>string}){return <section><h3>{title}</h3>{rows.length?rows.map(r=><article key={r.code}><div><code>{r.code}</code><span>{r.description}</span></div><strong>{value(r)}</strong></article>):<p>No qualifying codes.</p>}</section>}
function TimelineBars({values}:{values:number[]}){const buckets=[["0–3",0,3],["4–7",4,7],["8–14",8,14],["15–30",15,30],["31+",31,Infinity]] as const;const counts=buckets.map(([,min,max])=>values.filter(v=>v>=min&&v<=max).length);return <div className="timeline-bars" aria-label="Share of matched reopening records by elapsed days">{buckets.map(([label],i)=><article key={label}><strong>{counts[i]}</strong><i style={{width:`${values.length?counts[i]/values.length*100:0}%`}}/><span>{label} days · {percent(counts[i],values.length)}</span></article>)}</div>}
function FetchStateLabel({state,fetchedAt}:{state:FetchState;fetchedAt:string}){return <p className={`live-record-state ${state}`}>{state==="loading"?"Checking NYC Open Data…":state==="success"?`Live CAMIS history verified ${fmt.format(new Date(fetchedAt))}.`:state==="error"?"Live verification failed; no definitive status is available.":state==="empty"?"No history was returned for the analyzed period.":"Waiting for a restaurant selection."}</p>}
function LatestRecord({closure,latest}:{closure:InspectionEvent;latest:InspectionEvent[]}){if(!latest.length)return <p className="journey-empty">No official row is available for comparison.</p>;const before=new Set(closure.codes.map(c=>c.code));const after=new Set(latest.flatMap(event=>event.codes.map(c=>c.code)));return <div className="latest-record"><div className="latest-closure"><span>SELECTED CLOSURE</span><strong>{closure.date}</strong><p>{closure.action}</p></div><div className="latest-events"><span>NEWEST INSPECTION DATE · {latest[0].date}</span>{latest.map(event=><article key={event.id}><strong>{event.action}</strong><p>Score {event.score??"—"} · grade {event.grade??"not recorded"} · {event.codes.length} recorded codes</p><small>Dataset record date {event.recordDate??"not recorded"}</small></article>)}</div><div className="latest-code-change"><article><strong>{[...before].filter(c=>!after.has(c)).length}</strong><span>closure codes not recorded on newest date</span></article><article><strong>{[...before].filter(c=>after.has(c)).length}</strong><span>closure codes also recorded</span></article><article><strong>{[...after].filter(c=>!before.has(c)).length}</strong><span>other recorded codes</span></article></div></div>}
function descriptionFor(episodes:ClosureEpisode[],code:string){for(const e of episodes){const c=[...e.closure.codes,...(e.reopening?.codes??[]),...(e.laterClosure?.codes??[])].find(x=>x.code===code);if(c)return c.description}return "Recorded violation"}
function percent(n:number,d:number){return d?`${(n/d*100).toFixed(1)}%`:"—"}
